@app.post("/stop")
async def stop_stream(session_id: str = Query(..., description="Session ID to cancel")):
    sid = session_id.strip()
    with stop_lock:
        if sid in STOP_EVENTS:
            STOP_EVENTS[sid].set()
            del STOP_EVENTS[sid]
            return {"ok": True, "session_id": sid}
    return JSONResponse({"ok": False, "detail": "No active stream"}, status_code=404)
